#!/usr/bin/env bash
# verify-egress.sh: read-only check that the Pi's DOCKER-USER chain closes container-to-LAN egress.
#
# The egress rules are generated by server-host-base.sh (stronghold); this script only verifies them against the
# host-side files /etc/platform/egress-deny.cidrs and /etc/platform/egress-allow.cidrs (canonical IPv4 CIDRs,
# prefix 1-32, zero host bits, '#' comments and blank lines ignored; the deny file is required and non-empty, the
# allow file is optional). No address literals live in this repo: the CIDRs come from those files at run time.
#
# Static checks (always, over `sudo -n iptables -S DOCKER-USER`, normalized with the same canonical form as
# `server-host-base.sh normalize-rules`): rule order (conntrack/lo, four interface-pair RETURNs, allow RETURNs,
# drops, bridge RETURNs, final DROP), exactly one drop per deny CIDR for each of `-i br-+` and `-i docker0`, the
# allow RETURN set (udp/tcp port 53 per CIDR per interface) equal to the allow file, no `-o` RETURN lacking a bridge
# `-i`, no duplicate rule, no unknown rule; and the Docker daemon has IPv6 disabled.
#
# Opt-in probes (start containers; nothing starts without a flag; every resource is removed on every path):
#   --probe          a pinned tiny image on a throwaway bridge: the LAN default gateway (found on the host) must be
#                    blocked on a non-53 port (bounded timeout), a public lookup and connect must work, and two
#                    containers on the same bridge must reach each other (the docker0 pair RETURNs are checked
#                    statically only: default isolation separates docker0 from user bridges, so there is no probe).
#   --probe-inbound  publish a disposable container port on the LAN address and watch the final DROP counter while
#                    a LAN client (another machine) tries to connect; run once by you after install.
#
# Usage: verify-egress.sh [--host ALIAS] [--probe] [--probe-inbound]
#   --host   stream this script over one `ssh <alias> bash -s` call (the remote needs bash, sudo -n, iptables, docker);
#            an ssh failure passes through ssh's own status (255)
#
# Exit: 0 ok | 1 wrong rules, unusable check input (unreadable chain, missing/empty/invalid CIDR file), or a probe
#       connect that was refused or reachable (a recorded wrong-rules finding is never masked by a later exit 2) |
#       2 usage error, unmet --probe precondition, or another container error (image, missing tool, no route, failed
#       start). INT, TERM and HUP clean up the probe resources. Do not run two instances at once (the resource names
#       are fixed: platform-verify-egress-*); a SIGKILL can leave a container or network: remove them by those names.
#       The IPv6 check covers the default bridge and every network listed by `docker network ls`.
#
# Test overrides (env, test-only): VERIFY_EGRESS_DENY_FILE, VERIFY_EGRESS_ALLOW_FILE, VERIFY_EGRESS_DOCKER (default
# "sudo -n docker"), VERIFY_EGRESS_IPTABLES, VERIFY_EGRESS_IMAGE, VERIFY_EGRESS_PUBLIC_HOST, VERIFY_EGRESS_PROBE_PORT,
# VERIFY_EGRESS_INBOUND_WAIT.
set -euo pipefail

export LC_ALL=C
# iptables and ip live in /usr/sbin, which a non-root ssh user's PATH lacks
export PATH="$PATH:/usr/sbin:/sbin"

DENY_FILE="${VERIFY_EGRESS_DENY_FILE:-/etc/platform/egress-deny.cidrs}"
ALLOW_FILE="${VERIFY_EGRESS_ALLOW_FILE:-/etc/platform/egress-allow.cidrs}"
IMAGE="${VERIFY_EGRESS_IMAGE:-docker.io/library/busybox:1.37.0}"
PUBLIC_HOST="${VERIFY_EGRESS_PUBLIC_HOST:-example.com}"
PROBE_PORT="${VERIFY_EGRESS_PROBE_PORT:-443}"
INBOUND_WAIT="${VERIFY_EGRESS_INBOUND_WAIT:-30}"
read -r -a DOCKER <<<"${VERIFY_EGRESS_DOCKER:-sudo -n docker}"

readonly NET="platform-verify-egress-net"
readonly C_PROBE="platform-verify-egress-probe"
readonly C_SERVER="platform-verify-egress-b"
readonly C_BRIDGE="platform-verify-egress-a"
readonly C_INBOUND="platform-verify-egress-inbound"
readonly SERVER_PORT=8080

FAILURES=0
DENY_CIDRS=()
ALLOW_CIDRS=()
CONFIG_OK=1
PROBE_STARTED=0

pass() { printf 'PASS: %s\n' "$1"; }
fail() { printf 'FAIL: %s\n' "$1"; FAILURES=$((FAILURES + 1)); }
# die2 <message>: exit 2, unless a wrong-rules finding is already recorded (then exit 1, so it is never masked).
die2() {
  printf 'verify-egress: %s\n' "$1" >&2
  if [ "$FAILURES" -gt 0 ]; then
    printf 'verify-egress: %d check(s) failed\n' "$FAILURES"
    exit 1
  fi
  exit 2
}

# ---- shared pieces (kept identical to server-host-base.sh: validate_cidr_file, normalize_rules) ----

err() { printf '%s\n' "$1" >&2; }

# validate_cidr_file <path> <label>: prints the CIDR lines; returns 1 with a message on stderr at the first bad line.
validate_cidr_file() {
  local file="$1" label="$2" line n=0 a b c d pfx ip mask
  local -A seen=()
  local octet='(0|[1-9][0-9]{0,2})' re
  re="^$octet\\.$octet\\.$octet\\.$octet/(0|[1-9][0-9]?)\$"
  [ -r "$file" ] || { err "$label file $file is not readable"; return 1; }
  while IFS= read -r line || [ -n "$line" ]; do
    n=$((n + 1))
    if [[ "$line" == *$'\r'* ]]; then err "$label file $file line $n: CR (CRLF line endings) not allowed"; return 1; fi
    if [[ "$line" =~ [[:space:]]$ ]]; then err "$label file $file line $n: trailing whitespace not allowed"; return 1; fi
    case "$line" in "" | "#"*) continue ;; esac
    if [[ ! "$line" =~ $re ]]; then err "$label file $file line $n: not a canonical IPv4 CIDR with a prefix: $line"; return 1; fi
    a="${BASH_REMATCH[1]}"; b="${BASH_REMATCH[2]}"; c="${BASH_REMATCH[3]}"; d="${BASH_REMATCH[4]}"; pfx="${BASH_REMATCH[5]}"
    if [ "$a" -gt 255 ] || [ "$b" -gt 255 ] || [ "$c" -gt 255 ] || [ "$d" -gt 255 ]; then
      err "$label file $file line $n: octet out of range: $line"; return 1
    fi
    if [ "$pfx" -lt 1 ] || [ "$pfx" -gt 32 ]; then err "$label file $file line $n: prefix must be 1-32: $line"; return 1; fi
    ip=$(((a << 24) | (b << 16) | (c << 8) | d))
    mask=$(((0xFFFFFFFF << (32 - pfx)) & 0xFFFFFFFF))
    if [ $((ip & ~mask & 0xFFFFFFFF)) -ne 0 ]; then err "$label file $file line $n: host bits set: $line"; return 1; fi
    if [ -n "${seen[$line]:-}" ]; then err "$label file $file line $n: duplicate line: $line"; return 1; fi
    seen[$line]=1
    printf '%s\n' "$line"
  done < "$file"
}

# normalize_rules: stdin is `iptables -S` output; stdout is one canonical line per rule (chain name, -N/-P/-F/COMMIT
# lines and the implicit -m udp/-m tcp dropped; option order fixed). An unparseable line becomes `?? <line>`.
normalize_rules() {
  awk '
    /^(\*|:|COMMIT|-N |-P |-F |#)/ || NF == 0 { next }
    $1 != "-A" { print "?? " $0; next }
    {
      ct = ""; i = ""; o = ""; d = ""; p = ""; dp = ""; j = ""; bad = 0; mu = 0; mt = 0
      for (k = 3; k <= NF; k++) {
        t = $k
        if (t == "-i") i = $(++k)
        else if (t == "-o") o = $(++k)
        else if (t == "-d") d = $(++k)
        else if (t == "-p") p = $(++k)
        else if (t == "-j") j = $(++k)
        else if (t == "--dport") dp = $(++k)
        else if (t == "--ctstate") ct = $(++k)
        else if (t == "-m") {
          m = $(++k)
          if (m == "udp") mu = 1
          else if (m == "tcp") mt = 1
          else if (m != "conntrack") bad = 1
        } else bad = 1
      }
      if ((mu && p != "udp") || (mt && p != "tcp")) bad = 1
      if (j == "") bad = 1
      if (bad) { print "?? " $0; next }
      out = "-A"
      if (ct != "") out = out " -m conntrack --ctstate " ct
      if (i != "") out = out " -i " i
      if (o != "") out = out " -o " o
      if (d != "") out = out " -d " d
      if (p != "") out = out " -p " p
      if (dp != "") out = out " --dport " dp
      print out " -j " j
    }'
}

# ---- static checks ----

ipt() {
  local bin="${VERIFY_EGRESS_IPTABLES:-}"
  if [ -z "$bin" ]; then
    if [ -x /usr/sbin/iptables ]; then bin=/usr/sbin/iptables
    elif [ -x /sbin/iptables ]; then bin=/sbin/iptables
    else bin="$(command -v iptables || true)"
    fi
  fi
  [ -n "$bin" ] || { echo "iptables not found (looked in /usr/sbin, /sbin, PATH)" >&2; return 127; }
  sudo -n "$bin" "$@"
}

sorted() { printf '%s\n' "$1" | sed '/^$/d' | sort; }

# compare_sets <label> <want> <have>: newline lists compared as multisets; the difference is named on failure.
compare_sets() {
  local label="$1" want have extra missing
  want="$(sorted "$2")"
  have="$(sorted "$3")"
  if [ "$want" = "$have" ]; then
    pass "$label"
  else
    # sorted strips empty lines, so an empty set contributes no phantom entry to the diagnostic
    extra="$(comm -13 <(sorted "$want") <(sorted "$have") | tr '\n' ';')"
    missing="$(comm -23 <(sorted "$want") <(sorted "$have") | tr '\n' ';')"
    fail "$label differ (extra: ${extra:-none} missing: ${missing:-none})"
  fi
}

load_cidrs() {
  local out
  if [ ! -e "$DENY_FILE" ]; then
    fail "deny file $DENY_FILE is missing: the egress rules cannot be verified"
    CONFIG_OK=0
  elif ! out="$(validate_cidr_file "$DENY_FILE" deny)"; then
    fail "deny file $DENY_FILE is invalid"
    CONFIG_OK=0
  elif [ -z "$out" ]; then
    fail "deny file $DENY_FILE has no CIDR lines: refusing to pass vacuously"
    CONFIG_OK=0
  else
    mapfile -t DENY_CIDRS <<<"$out"
  fi
  if [ -e "$ALLOW_FILE" ] || [ -L "$ALLOW_FILE" ]; then
    if out="$(validate_cidr_file "$ALLOW_FILE" allow)"; then
      if [ -n "$out" ]; then mapfile -t ALLOW_CIDRS <<<"$out"; fi
    else
      fail "allow file $ALLOW_FILE is present but invalid"
      CONFIG_OK=0
    fi
  fi
  if [ "$CONFIG_OK" -eq 1 ]; then pass "deny file valid (${#DENY_CIDRS[@]} CIDR), allow file ${#ALLOW_CIDRS[@]} CIDR"; fi
}

check_chain() {
  local chain errfile line cat prev=0 cidr iface proto
  local conntrack=0 lo=0 final=0 last="" pairs="" allows="" drops="" bridges=""
  local want_pairs want_allows="" want_drops="" dups
  local -a lines=()
  local re_pair='^-A -i (br-\+|docker0) -o (br-\+|docker0) -j RETURN$'
  local re_allow='^-A -i (br-\+|docker0) -d [0-9./]+ -p (udp|tcp) --dport 53 -j RETURN$'
  local re_drop='^-A -i (br-\+|docker0) -d [0-9./]+ -j DROP$'
  local re_bridge='^-A -i (br-\+|docker0) -j RETURN$'

  errfile="$(mktemp)"
  if ! chain="$(ipt -S DOCKER-USER 2>"$errfile")"; then
    fail "cannot read the DOCKER-USER chain (sudo -n iptables -S DOCKER-USER): $chain $(cat "$errfile")"
    rm -f "$errfile"
    return 0
  fi
  rm -f "$errfile"
  if [ -z "$chain" ]; then fail "iptables -S DOCKER-USER printed nothing"; return 0; fi
  mapfile -t lines < <(printf '%s\n' "$chain" | normalize_rules)
  if [ "${#lines[@]}" -eq 0 ]; then fail "DOCKER-USER has no rules"; return 0; fi

  for line in "${lines[@]}"; do
    last="$line"
    if [[ "$line" == '?? '* ]]; then
      fail "unrecognised rule: ${line#\?\? }"; continue
    elif [ "$line" = '-A -m conntrack --ctstate RELATED,ESTABLISHED -j RETURN' ]; then cat=0; conntrack=$((conntrack + 1))
    elif [ "$line" = '-A -i lo -j RETURN' ]; then cat=0; lo=$((lo + 1))
    elif [[ "$line" =~ $re_pair ]]; then cat=1; pairs+="$line"$'\n'
    elif [[ "$line" == *' -o '* && "$line" == *' -j RETURN' ]]; then
      cat=1; fail "RETURN on -o without a bridge/docker0 -i pair (reopens the inbound backstop): $line"
    elif [[ "$line" =~ $re_allow ]]; then cat=2; allows+="$line"$'\n'
    elif [[ "$line" =~ $re_drop ]]; then cat=3; drops+="$line"$'\n'
    elif [[ "$line" =~ $re_bridge ]]; then cat=4; bridges+="$line"$'\n'
    elif [ "$line" = '-A -j DROP' ]; then cat=5; final=$((final + 1))
    else
      fail "unexpected rule: $line"; continue
    fi
    if [ "$cat" -lt "$prev" ]; then fail "rule out of order: $line"; else prev="$cat"; fi
  done

  if [ "$conntrack" -eq 1 ]; then pass "one conntrack RETURN"; else fail "expected exactly one RELATED,ESTABLISHED RETURN, found $conntrack"; fi
  if [ "$lo" -eq 1 ]; then pass "one loopback RETURN"; else fail "expected exactly one -i lo RETURN, found $lo"; fi
  if [ "$final" -eq 1 ] && [ "$last" = '-A -j DROP' ]; then pass "final rule is -j DROP"; else fail "the final rule must be a single -j DROP (last rule: $last)"; fi
  dups="$(printf '%s\n' "${lines[@]}" | sort | uniq -d | tr '\n' ';')"
  if [ -z "$dups" ]; then pass "no duplicate rule"; else fail "duplicate rules: $dups"; fi

  want_pairs=$'-A -i br-+ -o br-+ -j RETURN\n-A -i br-+ -o docker0 -j RETURN\n-A -i docker0 -o br-+ -j RETURN\n-A -i docker0 -o docker0 -j RETURN'
  compare_sets "the four interface-pair RETURNs" "$want_pairs" "$pairs"
  compare_sets "bridge RETURNs (docker0, br-+)" $'-A -i br-+ -j RETURN\n-A -i docker0 -j RETURN' "$bridges"
  for cidr in ${ALLOW_CIDRS[@]+"${ALLOW_CIDRS[@]}"}; do
    for iface in br-+ docker0; do
      for proto in udp tcp; do want_allows+="-A -i $iface -d $cidr -p $proto --dport 53 -j RETURN"$'\n'; done
    done
  done
  compare_sets "allow RETURNs equal the allow file" "$want_allows" "$allows"
  for cidr in ${DENY_CIDRS[@]+"${DENY_CIDRS[@]}"}; do
    for iface in br-+ docker0; do want_drops+="-A -i $iface -d $cidr -j DROP"$'\n'; done
  done
  compare_sets "one drop per deny CIDR per interface" "$want_drops" "$drops"
}

check_ipv6() {
  local v ids net bad=""
  if ! v="$("${DOCKER[@]}" network inspect bridge --format '{{.EnableIPv6}}' 2>&1)"; then
    fail "cannot inspect the default Docker bridge to confirm IPv6 is disabled: $v"
    return 0
  elif [ "$v" != "false" ]; then
    fail "Docker IPv6 is enabled or unreadable ('$v'): the iptables-only rules can be bypassed"
    return 0
  fi
  if ! ids="$("${DOCKER[@]}" network ls -q 2>&1)"; then
    fail "cannot list the Docker networks to confirm IPv6 is disabled on each: $ids"
    return 0
  fi
  for net in $ids; do
    if ! v="$("${DOCKER[@]}" network inspect "$net" --format '{{.EnableIPv6}}' 2>&1)" || [ "$v" != "false" ]; then
      bad+="$net "
    fi
  done
  if [ -z "$bad" ]; then
    pass "Docker IPv6 disabled (default bridge and every listed network)"
  else
    fail "Docker IPv6 is enabled or unreadable on network(s): ${bad}(the iptables-only rules can be bypassed)"
  fi
}

# ---- probes ----

remove_probe_resources() {
  local n
  for n in "$C_PROBE" "$C_SERVER" "$C_BRIDGE" "$C_INBOUND"; do
    "${DOCKER[@]}" rm -f "$n" >/dev/null 2>&1 || true
  done
  "${DOCKER[@]}" network rm "$NET" >/dev/null 2>&1 || true
}

cleanup() {
  local rc=$?
  trap - EXIT
  if [ "$PROBE_STARTED" -eq 1 ]; then remove_probe_resources; fi
  exit "$rc"
}

ip_int() {
  local a b c d
  IFS=. read -r a b c d <<<"$1"
  echo $(((a << 24) | (b << 16) | (c << 8) | d))
}

# cidr_has <cidr> <ip>
cidr_has() {
  local net="${1%/*}" pfx="${1#*/}" mask
  mask=$(((0xFFFFFFFF << (32 - pfx)) & 0xFFFFFFFF))
  [ $(($(ip_int "$2") & mask)) -eq $(($(ip_int "$net") & mask)) ]
}

# The snippets below are single-quoted on purpose: they expand inside the container, not here.
# shellcheck disable=SC2016
# The in-container connect helper: prints open | blocked (bounded timeout) | refused | error.
# The outer `timeout` outlasts nc's own -w so a dropped SYN is killed, never left hanging.
# busybox nc -w exits 1 with NO message when its own connect timeout fires (seen on the Pi), so a silent rc 1 is
# blocked; a refusal, reset or any other nc message keeps its own meaning above.
readonly CONN_FN='conn() {
  err=$(timeout 6 nc -w 3 "$1" "$2" </dev/null 2>&1 >/dev/null); rc=$?
  case $rc in
    0) echo open ;;
    124|137|143) echo blocked ;;
    *) case $err in
         *efused*|*eset*) echo refused ;;
         *"timed out"*|*imeout*) echo blocked ;;
         "") if [ "$rc" -eq 1 ]; then echo blocked; else echo error; fi ;;
         *) echo error ;;
       esac ;;
  esac
}
'
# shellcheck disable=SC2016
readonly PROBE_SNIPPET="${CONN_FN}"'
for t in nc timeout nslookup; do
  command -v "$t" >/dev/null 2>&1 || { echo "TOOLS=missing-$t"; exit 0; }
done
echo TOOLS=ok
if nslookup "$3" >/dev/null 2>&1; then echo LOOKUP=ok; else echo LOOKUP=fail; fi
echo "GATEWAY=$(conn "$1" "$2")"
echo "PUBLIC=$(conn "$3" 443)"
'
# shellcheck disable=SC2016
readonly CONNECT_SNIPPET="${CONN_FN}"'
command -v nc >/dev/null 2>&1 && command -v timeout >/dev/null 2>&1 || { echo RESULT=error; exit 0; }
echo "RESULT=$(conn "$1" "$2")"
'

docker_run() { "${DOCKER[@]}" run --cap-drop ALL --security-opt no-new-privileges "$@"; }

# connect_from <container-name> <network-args...> -- <host> <port>: prints open|blocked|refused|error
# (docker failure -> die2). Network args are passed through (empty for the default docker0 bridge).
connect_from() {
  local name="$1" out token="" line
  shift
  local -a netargs=()
  while [ "$1" != "--" ]; do netargs+=("$1"); shift; done
  shift
  out="$(docker_run --rm --name "$name" ${netargs[@]+"${netargs[@]}"} "$IMAGE" sh -c "$CONNECT_SNIPPET" connect "$1" "$2")" \
    || die2 "container $name failed to run (image, tool or start error)"
  while IFS= read -r line; do
    case "$line" in RESULT=*) token="${line#RESULT=}" ;; esac
  done <<<"$out"
  [ -n "$token" ] || die2 "container $name printed no result"
  printf '%s' "$token"
}

default_gateway() {
  ip -4 route show default 2>/dev/null | awk '$1 == "default" { for (i = 1; i < NF; i++) if ($i == "via") { print $(i + 1); exit } }' || true
}

run_probe() {
  local gw cidr covered=0 out line tools="" lookup="" gwres="" pubres=""
  local ip_re='^([0-9]{1,3}\.){3}[0-9]{1,3}$'
  gw="$(default_gateway)"
  [ -n "$gw" ] || die2 "no LAN default gateway found in the host routing table: cannot probe"
  [[ "$gw" =~ $ip_re ]] || die2 "the default gateway read from the routing table is not an IPv4 address: cannot probe"
  for cidr in "${DENY_CIDRS[@]}"; do
    if cidr_has "$cidr" "$gw"; then covered=1; fi
  done
  [ "$covered" -eq 1 ] || die2 "the LAN default gateway is not covered by any deny CIDR in $DENY_FILE: the probe would prove nothing"
  [ "$PROBE_PORT" != "53" ] || die2 "the probe port must not be 53 (a resolver allow exception would mask the drop)"

  PROBE_STARTED=1
  remove_probe_resources
  "${DOCKER[@]}" network create "$NET" >/dev/null || die2 "cannot create the throwaway bridge network $NET"

  out="$(docker_run --rm --name "$C_PROBE" --network "$NET" "$IMAGE" sh -c "$PROBE_SNIPPET" probe "$gw" "$PROBE_PORT" "$PUBLIC_HOST")" \
    || die2 "the probe container failed to run (image, tool or start error)"
  while IFS= read -r line; do
    case "$line" in
      TOOLS=*) tools="${line#TOOLS=}" ;;
      LOOKUP=*) lookup="${line#LOOKUP=}" ;;
      GATEWAY=*) gwres="${line#GATEWAY=}" ;;
      PUBLIC=*) pubres="${line#PUBLIC=}" ;;
    esac
  done <<<"$out"
  [ "$tools" = "ok" ] || die2 "the probe image lacks a needed tool (${tools:-no output})"
  case "$gwres" in blocked | open | refused) ;; *) die2 "the gateway connect failed with a container/network error (${gwres:-no output})" ;; esac
  case "$pubres" in open | blocked | refused) ;; *) die2 "the public connect failed with a container/network error (${pubres:-no output})" ;; esac

  case "$gwres" in
    blocked) pass "gateway port $PROBE_PORT blocked (bounded timeout)" ;;
    refused) fail "gateway port $PROBE_PORT was refused: the container reached the gateway" ;;
    open) fail "gateway port $PROBE_PORT is reachable from a container: egress is NOT blocked" ;;
  esac
  if [ "$lookup" = "ok" ]; then pass "container DNS lookup of the public host works"; else fail "container DNS lookup of the public host failed"; fi
  if [ "$pubres" = "open" ]; then pass "public connect works"; else fail "public connect from a container did not succeed ($pubres)"; fi

  probe_container_to_container
}

probe_container_to_container() {
  local res
  docker_run -d --name "$C_SERVER" --network "$NET" "$IMAGE" sh -c "exec httpd -f -p $SERVER_PORT -h /tmp" >/dev/null \
    || die2 "cannot start the container-to-container server container"
  res=refused
  for _ in 1 2 3 4 5; do
    res="$(connect_from "$C_BRIDGE" --network "$NET" -- "$C_SERVER" "$SERVER_PORT")" || exit $?
    [ "$res" = "refused" ] || break
    sleep 1
  done
  case "$res" in
    open) pass "bridge/bridge: a container reaches another on the same bridge" ;;
    error) die2 "bridge/bridge connect failed with a container/network error" ;;
    *) fail "bridge/bridge: container-to-container connect did not succeed ($res)" ;;
  esac
}

# drop_pkts: packet count of the chain's final catch-all DROP (in/out columns are both `*`).
drop_pkts() {
  ipt -L DOCKER-USER -n -v -x | awk '$3 == "DROP" && $6 == "*" && $7 == "*" { p = $1 } END { print p }'
}

run_probe_inbound() {
  local gw lan hostport before after
  gw="$(default_gateway)"
  [ -n "$gw" ] || die2 "no LAN default gateway found: cannot pick the LAN address to publish on"
  lan="$(ip -4 route get "$gw" 2>/dev/null | awk '{ for (i = 1; i < NF; i++) if ($i == "src") { print $(i + 1); exit } }' || true)"
  [ -n "$lan" ] || die2 "cannot determine the host LAN address"
  before="$(drop_pkts)" || die2 "cannot read the DOCKER-USER packet counters"
  [[ "$before" =~ ^[0-9]+$ ]] || die2 "the final DROP counter was not found in iptables -L output"

  PROBE_STARTED=1
  remove_probe_resources
  docker_run -d --name "$C_INBOUND" -p "$lan::$SERVER_PORT" "$IMAGE" sh -c "exec httpd -f -p $SERVER_PORT -h /tmp" >/dev/null \
    || die2 "cannot start the published-port container"
  hostport="$("${DOCKER[@]}" port "$C_INBOUND" "$SERVER_PORT/tcp" | head -n 1)" || die2 "cannot read the published port"
  [ -n "$hostport" ] || die2 "the container published no port"
  printf 'INBOUND: from ANOTHER LAN machine connect to %s now (expect a timeout); waiting %ss\n' "$hostport" "$INBOUND_WAIT"
  sleep "$INBOUND_WAIT"
  after="$(drop_pkts)" || die2 "cannot read the DOCKER-USER packet counters"
  [[ "$after" =~ ^[0-9]+$ ]] || die2 "the final DROP counter was not found in iptables -L output"
  if [ "$after" -gt "$before" ]; then
    pass "inbound: final DROP counter rose by $((after - before)) (operator-confirmed LAN attempt required)"
  else
    fail "inbound: final DROP counter rose by 0 (operator-confirmed LAN attempt required; none seen, or the backstop is not dropping)"
  fi
}

# ---- main ----

main() {
  local host="" do_probe=0 do_inbound=0 fwd=""
  while [ $# -gt 0 ]; do
    case "$1" in
      --host) [ $# -ge 2 ] || { err "missing value for --host"; return 2; }; host="$2"; shift 2 ;;
      --probe) do_probe=1; fwd+=" --probe"; shift ;;
      --probe-inbound) do_inbound=1; fwd+=" --probe-inbound"; shift ;;
      -h | --help) sed -n '2,/^set -/{/^set -/!p;}' "${BASH_SOURCE[0]}"; return 0 ;;
      *) err "unknown argument: $1"; return 2 ;;
    esac
  done
  if [ -n "$host" ]; then
    exec ssh -o BatchMode=yes -- "$host" "bash -s --$fwd" < "${BASH_SOURCE[0]}"
  fi

  trap cleanup EXIT
  trap 'exit 130' INT
  trap 'exit 143' TERM
  trap 'exit 129' HUP

  load_cidrs
  if [ "$CONFIG_OK" -eq 1 ]; then check_chain; fi
  check_ipv6
  if [ "$FAILURES" -gt 0 ]; then
    printf 'verify-egress: %d check(s) failed\n' "$FAILURES"
    if [ "$do_probe" -eq 1 ] || [ "$do_inbound" -eq 1 ]; then echo "verify-egress: probes skipped because the static checks failed"; fi
    return 1
  fi
  if [ "$do_probe" -eq 1 ]; then run_probe; fi
  if [ "$do_inbound" -eq 1 ]; then run_probe_inbound; fi
  if [ "$FAILURES" -gt 0 ]; then
    printf 'verify-egress: %d check(s) failed\n' "$FAILURES"
    return 1
  fi
  echo "verify-egress: OK"
}

main "$@"
